
import re

# Words frequently discussed in research on AI writing.
# These are clues, not proof that text was generated by AI.
AI_VOCABULARY = [
    "delve",
    "intricate",
    "pivotal",
    "landscape",
    "interplay",
    "underscore"
]


def analyze_patterns(text: str) -> dict:
    """Identify linguistic patterns in a passage."""

    # Find any vocabulary associated with AI as complete words
    vocabulary_found = [
        word for word in AI_VOCABULARY
        if re.search(r"\b" + re.escape(word) + r"\b", text.lower())
    ]

    # Count em dashes
    em_dash_count = text.count("—")

    # Find Oxford commas 
    oxford_comma_count = len(
        re.findall(r",\s+(?:and|or)\b", text, flags=re.IGNORECASE)
    )

    # Find "not just X, but Y" sentence structures
    negative_parallelism_count = len(
        re.findall(
            r"\bnot\s+(?:just|only)\b[^.!?]{0,100}?,\s*but\b",
            text,
            flags=re.IGNORECASE
        )
    )

    return {
        "ai_vocabulary": vocabulary_found,
        "em_dash_count": em_dash_count,
        "oxford_comma_count": oxford_comma_count,
        "negative_parallelism_count": negative_parallelism_count
    }


if __name__ == "__main__":
    sample = (
        "We need to delve into this intricate landscape—"
        "not just to understand the challenges, but to improve outcomes. "
        "The system uses data, models, and evaluation."
    )

    print(analyze_patterns(sample))
